"use client";
import * as React from "react";
import { cn } from "@/lib/utils";
import { supportDestination } from "@/lib/sahajiv/reference-layouts";
import { useMotionVisibility } from "@/lib/sahajiv-motion/use-motion-visibility";
import { assignMotionRef } from "@/lib/sahajiv-motion/refs";
export type BuyMeCoffeeProps=Omit<React.ComponentProps<"a">,"href"|"children"|"title"> & {href:string;title?:string;description?:string;actionLabel?:string;tone?:"pink"|"olive"|"blue"|"yellow"};
/** A support invitation and native destination link, with no payment behavior. */
export function BuyMeCoffee({href,title="Keep good things growing.",description="A little support makes room for the next useful idea.",actionLabel="Support this work",tone="yellow",className,ref,...props}:BuyMeCoffeeProps){
 const host=React.useRef<HTMLAnchorElement>(null),{enabled,inView}=useMotionVisibility(host),destination=supportDestination(href);
 const hostRef=React.useCallback((node:HTMLAnchorElement|null)=>{host.current=node;return assignMotionRef(ref,node);},[ref]);
 return <a {...props} ref={hostRef} href={destination} aria-disabled={!destination||undefined} className={cn("v-buy-me-coffee",className)} data-slot="buy-me-coffee" data-motion={enabled&&inView?"on":"off"} style={{...props.style,"--support-tone":`var(--v-${tone})`} as React.CSSProperties} rel={props.target==="_blank"?"noopener noreferrer":props.rel}>
 <span className="v-buy-me-coffee__poster" aria-hidden="true">a little<br/>goes a<br/>long way.</span>
 <span className="v-buy-me-coffee__art" aria-hidden="true"><svg viewBox="0 0 180 170" fill="none"><path className="v-buy-me-coffee__steam" d="M66 42C47 26 83 25 65 8M94 42C75 26 111 25 93 8" stroke="currentColor" strokeWidth="3" strokeLinecap="round"/><path d="M122 65H139C158 65 158 96 140 98H121" stroke="currentColor" strokeWidth="5"/><path d="M38 58H128L121 127Q118 148 83 148Q48 148 45 127Z" fill="var(--support-tone)" stroke="currentColor" strokeWidth="3"/><ellipse cx="83" cy="59" rx="44" ry="8" fill="var(--v-paper)" stroke="currentColor" strokeWidth="3"/><path d="M66 103C58 84 82 81 84 96C87 81 112 85 99 104L83 119Z" fill="var(--v-ink)"/><path d="M27 153H143" stroke="currentColor" strokeWidth="3" strokeLinecap="round"/></svg></span>
 <span className="v-buy-me-coffee__copy"><strong>{title}</strong><span>{description}</span></span>
 <span className="v-buy-me-coffee__action">{destination?actionLabel:"Support link unavailable"}<span aria-hidden="true">↗</span></span>
 </a>;
}

@layer sahajiv-states {
.v-buy-me-coffee{position:relative;display:grid;align-content:end;gap:18px;width:min(100%,380px);min-height:440px;overflow:hidden;padding:28px;border:1px solid var(--v-edge);border-radius:28px;background:var(--v-paper);color:var(--v-ink);text-decoration:none;isolation:isolate}.v-buy-me-coffee__poster{position:absolute;top:20px;left:24px;font:clamp(38px,7vw,58px)/.9 var(--font-display);font-weight:700;letter-spacing:-.045em;color:var(--v-text);transition:transform .45s,opacity .35s}.v-buy-me-coffee__art{position:absolute;top:25px;right:-12px;width:180px;transform:translate(15px,62px) rotate(-13deg) scale(.8);transition:transform .6s cubic-bezier(.22,1,.36,1);transform-origin:center}.v-buy-me-coffee__art svg{width:100%;height:auto}.v-buy-me-coffee__steam{opacity:0;transition:opacity .3s}.v-buy-me-coffee__copy{position:relative;display:grid;gap:10px;padding-top:225px}.v-buy-me-coffee__copy strong{font:25px/1.1 var(--font-display)}.v-buy-me-coffee__copy>span{font-size:14px;line-height:1.45;color:var(--v-text-2)}.v-buy-me-coffee__action{display:flex;justify-content:space-between;align-items:center;gap:16px;font-size:14px;font-weight:600;border-top:1px solid var(--v-border);padding-top:16px}.v-buy-me-coffee:focus-visible{outline:3px solid var(--v-brand);outline-offset:4px}.v-buy-me-coffee[data-motion=on]:is(:hover,:focus-visible) .v-buy-me-coffee__poster{transform:translateY(-12px) scale(.85);opacity:.13}.v-buy-me-coffee[data-motion=on]:is(:hover,:focus-visible) .v-buy-me-coffee__art{transform:translate(-55px,8px) rotate(0) scale(1.25)}.v-buy-me-coffee[data-motion=on]:is(:hover,:focus-visible) .v-buy-me-coffee__steam{opacity:1}.v-buy-me-coffee[aria-disabled=true]{opacity:.65}.v-buy-me-coffee[data-motion=off] *{transition:none}@media(prefers-reduced-motion:reduce){.v-buy-me-coffee *{transition:none}}@media(hover:none){.v-buy-me-coffee__steam{opacity:1}}

}
